content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 16px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--card-bg);
  padding: 20px 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
}

.main-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.chart-card,
.list-card,
.details-card {
  background: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.details-card {
  grid-column: 1 / -1;
}

.expense-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 300px;
  overflow-y: auto;
  padding-right: 4px;
}

.expense-list::-webkit-scrollbar {
  width: 6px;
}

.expense-list::-webkit-scrollbar-track {
  background: var(--bg-color);
  border-radius: 4px;
}

.expense-list::-webkit-scrollbar-thumb {
  background: var(--border-color);
  border-radius: 4px;
}

.expense-list::-webkit-scrollbar-thumb:hover {
  background: var(--text-muted);
}

.expense-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  background: var(--bg-color);
  border-radius: 8px;
  border: 1px solid var(--border-color);
  cursor: pointer;
  transition: background-color 0.2s, border-color 0.2s;
}

.expense-row:hover {
  background: #f1f5f9;
  border-color: var(--primary-color);
}

.amount-display {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--primary-color);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 16px;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-danger {
  background-color: var(--danger-color);
  color: white;
}

.btn-danger:hover {
  background-color: var(--danger-hover);
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.input-group label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
}

.input-group input,
.input-group textarea {
  padding: 10px 12px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  font-size: 1rem;
  outline: none;
  transition: border-color 0.2s;
  font-family: inherit;
}

.input-group input:focus,
.input-group textarea:focus {
  border-color: var(--primary-color);
}

@media (max-width: 768px) {
  .app-container {
    padding: 16px 12px;
    gap: 16px;
  }

  .header {
    padding: 16px;
    flex-direction: column;
    gap: 8px;
    align-items: flex-start;
  }

  .title {
    font-size: 1.25rem;
  }

  .main-layout {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .chart-card,
  .list-card,
  .details-card {
    padding: 16px;
    gap: 12px;
  }

  .amount-display {
    font-size: 1.5rem;
  }
}

export interface ExpenseItem {
  id: string;
  name: string;
  amount: number;
  color: string;
  memo: string;
  date?: string;
  category?: string;
}

import { useState } from 'react';
import { ExpenseItem } from './types';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer } from 'recharts';

const INITIAL_EXPENSES: ExpenseItem[] = [
  { id: '1', name: '食費', amount: 45000, color: '#4f46e5', memo: 'スーパーでの食材買い出し、外食など' },
  { id: '2', name: '家賃', amount: 80000, color: '#06b6d4', memo: '毎月のマンション家賃' },
  { id: '3', name: '光熱費', amount: 12000, color: '#10b981', memo: '電気・ガス・水道代の合算' },
  { id: '4', name: '通信費', amount: 8000, color: '#f59e0b', memo: 'スマートフォン・自宅Wi-Fi' },
  { id: '5', name: '娯楽費', amount: 15000, color: '#ef4444', memo: '映画、趣味、交際費など' },
];

const PRESET_COLORS = ['#4f46e5', '#06b6d4', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

export default function App() {
  const [expenses, setExpenses] = useState<ExpenseItem[]>(INITIAL_EXPENSES);
  const [selectedItem, setSelectedItem] = useState<ExpenseItem | null>(INITIAL_EXPENSES[0]);

  const [name, setName] = useState('');
  const [amount, setAmount] = useState('');
  const [memo, setMemo] = useState('');
  const [color, setColor] = useState(() => PRESET_COLORS[INITIAL_EXPENSES.length % PRESET_COLORS.length]);

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    const numAmount = Number(amount);
    if (!name || isNaN(numAmount) || numAmount <= 0) return;

    const assignedColor = color || PRESET_COLORS[expenses.length % PRESET_COLORS.length];

    const newItem: ExpenseItem = {
      id: Date.now().toString(),
      name,
      amount: numAmount,
      color: assignedColor,
      memo
    };
    const updatedExpenses = [...expenses, newItem];
    setExpenses(updatedExpenses);
    if (!selectedItem) {
      setSelectedItem(newItem);
    }
    setName('');
    setAmount('');
    setMemo('');
    setColor(PRESET_COLORS[updatedExpenses.length % PRESET_COLORS.length]);
  };

  const handleDelete = (id: string) => {
    if (!window.confirm('本当にこの項目を削除しますか？')) {
      return;
    }
    const updated = expenses.filter(item => item.id !== id);
    setExpenses(updated);
    if (selectedItem?.id === id) {
      setSelectedItem(updated[0] || null);
    }
  };

  const totalAmount = expenses.reduce((sum, item) => sum + item.amount, 0);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">家計支出管理アプリ</h1>
        <div style={{ fontWeight: 600 }}>合計: ￥{totalAmount.toLocaleString()}</div>
      </header>

      <div className="main-layout">
        <div className="chart-card">
          <h2>支出内訳円グラフ</h2>
          <div style={{ width: '100%', height: 260 }}>
            <ResponsiveContainer>
              <PieChart>
                <Pie
                  data={expenses}
                  dataKey="amount"
                  nameKey="name"
                  cx="50%"
                  cy="50%"
                  outerRadius={90}
                  innerRadius={40}
                  onClick={(data: unknown) => {
                    const record = data as Record<string, unknown>;
                    const payload = (record?.payload ?? record) as Partial<ExpenseItem>;
                    const found = expenses.find(item => item.id === payload?.id || item.name === payload?.name);
                    if (found) {
                      setSelectedItem(found);
                    }
                  }}
                >
                  {expenses.map((entry) => (
                    <Cell key={`cell-${entry.id}`} fill={entry.color} cursor="pointer" />
                  ))}
                </Pie>
                <Tooltip formatter={(value: number) => `￥${value.toLocaleString()}`} />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="list-card">
          <h2>支出項目一覧</h2>
          <ul className="expense-list">
            {expenses.map((item) => (
              <li
                key={item.id}
                className="expense-row"
                onClick={() => setSelectedItem(item)}
              >
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <span style={{ width: 12, height: 12, borderRadius: '50%', backgroundColor: item.color }} />
                  <span>{item.name}</span>
                </div>
                <span>￥{item.amount.toLocaleString()}</span>
              </li>
            ))}
          </ul>

          <form onSubmit={handleAdd} style={{ display: 'flex', flexDirection: 'column', gap: '12px', marginTop: '12px' }}>
            <h3 style={{ fontSize: '1rem' }}>支出の追加</h3>
            <div className="input-group">
              <label>項目名</label>
              <input type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="例: 交通費" required />
            </div>
            <div className="input-group">
              <label>金額 (円)</label>
              <input type="number" value={amount} min="1" onChange={(e) => setAmount(e.target.value)} placeholder="例: 5000" required />
            </div>
            <div className="input-group">
              <label>メモ</label>
              <textarea value={memo} onChange={(e) => setMemo(e.target.value)} placeholder="メモを入力..." rows={2} />
            </div>
            <div className="input-group">
              <label>カラー</label>
              <input type="color" value={color} onChange={(e) => setColor(e.target.value)} style={{ height: '40px', padding: '2px', cursor: 'pointer' }} />
            </div>
            <button type="submit" className="btn btn-primary">追加する</button>
          </form>
        </div>

        <div className="details-card">
          <h2>項目詳細</h2>
          {selectedItem ? (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <span style={{ width: 16, height: 16, borderRadius: '50%', backgroundColor: selectedItem.color }} />
                <h3 style={{ fontSize: '1.25rem' }}>{selectedItem.name}</h3>
              </div>
              <div className="amount-display">￥{selectedItem.amount.toLocaleString()}</div>
              <div>
                <strong style={{ color: 'var(--text-muted)' }}>メモ:</strong>
                <p style={{ marginTop: '4px' }}>{selectedItem.memo || 'メモはありません'}</p>
              </div>
              <div>
                <button 
                  className="btn btn-danger" 
                  onClick={() => handleDelete(selectedItem.id)}
                >
                  この項目を削除
                </button>
              </div>
            </div>
          ) : (
            <p style={{ color: 'var(--text-muted)' }}>項目を選択してください</p>
          )}
        </div>
      </div>
    </div>
  );
}
